<div style="max-width:900px;margin:0 auto"><h1>Quiz</h1><p><?=count($quiz['questions'])?> question(s)</p><form method="post" action="<?=url('student/quiz-submit.php')?>"><?=CSRF::field()?><input type="hidden" name="quiz_id" value="<?= (int)$quiz['id']?>">
<?php foreach($quiz['questions'] as $i=>$q):$data=json_decode($q['answer_data']??'',true)?:[];?><div class="card"><span class="badge"><?=strtoupper(e($q['type']))?></span><h3>Question <?= $i+1 ?></h3><p style="white-space:pre-wrap"><?=e($q['question_text'])?></p>
<?php if($q['type']==='mcq'):foreach(($data['options']??[]) as $opt):?><label style="display:block;margin:.5rem 0"><input type="radio" name="answers[<?= (int)$q['quiz_question_id']?>]" value="<?=e($opt)?>"> <?=e($opt)?></label><?php endforeach;?>
<?php elseif($q['type']==='match'):foreach(($data['left_items']??[]) as $left):?><label><?=e($left)?> <select name="answers[<?= (int)$q['quiz_question_id']?>][<?=e($left)?>]"><option value="">Select an answer</option><?php foreach(($data['right_items']??[]) as $right):?><option value="<?=e($right)?>"><?=e($right)?></option><?php endforeach;?></select></label><br><?php endforeach;?>
<?php else:?><textarea class="form-control" rows="4" name="answers[<?= (int)$q['quiz_question_id']?>]"></textarea><?php endif;?></div><?php endforeach;?>
<button class="btn btn-primary">Submit Quiz</button></form><form method="post" action="<?=url('student/quiz-discard.php')?>" onsubmit="return confirm('Discard this quiz? All current answers will be lost.');"><?=CSRF::field()?><input type="hidden" name="quiz_id" value="<?= (int)$quiz['id']?>"><button class="btn btn-secondary">Discard Quiz</button></form></div>
